// sigdyn.mjs — signature-dynamics periodicity analysis (final closure attempt for Assumption M).
// FORMAL SETUP: the master at class h is controlled (Lemma D + G(a)) by the window signature
//   sig(h) = ( (A_j mod 2^K, H_j) for j in [j0(h), j0(h)+W) , budget b = h-1-tau_j0 ),
// with K = 32 (parities read at most A mod 2^{H+2}, H <= 24 in range) and W = 40.
// The signature sequence is the projection of the ladder's residue sequence A_j mod 2^K,
// generated by the exact alpha-walk alpha_{j+1} = alpha_j + dAlpha(nu2(alpha_j+1)).
// PERIODICITY QUESTION: does the residue sequence (hence the signature dynamics) enter a
// cycle within the machine range? Cycle detection by hashing every residue.
// RECORD SCHEDULE: a signature cycle with K bits existing forever would cap nu2 < K; the
// true walk hits nu2 = K at round R_K ~ 2^(K-2) (measured: 17@19024, 19@76096, 21@304383,
// 22@1217531, 24@4870122). This run extends the schedule and detects residue cycles.
// Usage: node sigdyn.mjs [K=32]
import { readFileSync, writeFileSync } from 'fs';

const K = +(process.argv[2] ?? 32);
const MOD = 2n ** BigInt(K);
const DA = [];
for (const l of readFileSync('sym4-table.txt', 'utf8').split('\n')) {
  const m = l.match(/h=(\d+).*da=(\d+) dt=(\d+)/);
  if (m) DA[+m[1]] = BigInt(m[2]);
}
const ladder = JSON.parse(readFileSync('ladder.json', 'utf8')).ladder;
const v2mod = (a) => { let x = (a + 1n) % MOD; if (x === 0n) return K; let c = 0; while (x % 2n === 0n) { c++; x /= 2n; } return c; };
// walk the residues, detect repeats via Map (residue -> first index)
const seen = new Map();
let a = 7n, repeatIdx = -1, repeatPrev = -1;
const N = Math.min(ladder.length, 2400000);
for (let j = 0; j < N; j++) {
  // verify against ladder while available (integrity)
  if (j < ladder.length && BigInt(ladder[j].A) % MOD !== a % MOD) { console.log(`MISMATCH vs ladder at j=${j} — table/ladder inconsistent`); break; }
  if (seen.has(a % MOD)) { repeatPrev = seen.get(a % MOD); repeatIdx = j; break; }
  seen.set(a % MOD, j);
  const h = v2mod(a);
  if (DA[h] === undefined) { console.log(`nu2=${h} exceeds table at j=${j} (record schedule reached K)`); break; }
  a = (a + DA[h]);
}
if (repeatIdx >= 0) {
  console.log(`RESIDUE CYCLE mod 2^${K}: first repeat at j=${repeatIdx}, previously seen at j=${repeatPrev} => pre-period ${repeatPrev}, cycle length ${repeatIdx - repeatPrev}`);
  // task-3 replay verification: re-walk from repeatPrev for the cycle length and check return
  let b = 7n; for (let j = 0; j < repeatPrev; j++) b += DA[v2mod(b)];
  const start = b % MOD;
  for (let j = 0; j < repeatIdx - repeatPrev; j++) b += DA[v2mod(b)];
  console.log(`replay check: after ${repeatIdx - repeatPrev} steps from j=${repeatPrev}, residue returned to start: ${b % MOD === start} (exact match: ${b % MOD === start})`);
  writeFileSync('sigdyn-result.json', JSON.stringify({ K, preperiod: repeatPrev, cycleLen: repeatIdx - repeatPrev }));
} else {
  console.log(`NO residue repeat within ${N} ladder positions (K=${K}): the residue orbit is still in its transient — no signature cycle detectable in range.`);
}
// record schedule extension: first j where nu2 reaches each level (exact, using ladder A's)
const firstAt = {};
for (let j = 0; j < ladder.length; j++) {
  const A = BigInt(ladder[j].A);
  let x = A + 1n, c = 0; while (x % 2n === 0n) { c++; x /= 2n; }
  if (firstAt[c] === undefined) firstAt[c] = j;
}
const lv = Object.keys(firstAt).map(Number).sort((x, y) => x - y);
console.log('record schedule (level -> first ladder index): ' + lv.filter(x => x >= 15).map(x => `${x}@${firstAt[x]}`).join(' '));
const ratios = [];
for (let i = 1; i < lv.length; i++) if (lv[i] >= 16 && lv[i - 1] >= 16) ratios.push((firstAt[lv[i]] / firstAt[lv[i - 1]]).toFixed(2));
console.log('record spacing ratios: ' + ratios.join(' '));
